// Helper to get heat color by average price per sqm
export function getHeatmapColor(avgPrice) {
  if (avgPrice >= 1400) return "#E11D48"; // Rose 600 (Luxury/Highest)
  if (avgPrice >= 1100) return "#F59E0B"; // Amber 500
  if (avgPrice >= 850) return "#3B82F6"; // Blue 500
  if (avgPrice >= 680) return "#10B981"; // Emerald 500
  return "#64748B"; // Slate 500 (Most affordable)
}
